    async fn write_continuation_projection<W: AsyncWrite + Unpin>(
        &self,
        writer: &mut W,
        payload: Vec<u8>,
    ) -> Result<(), IpcBridgeError> {
        let value: serde_json::Value =
            serde_json::from_slice(&payload).map_err(|error| FrameError::Io(error.to_string()))?;
        let number = |name: &str| {
            value
                .get(name)
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0)
        };
        let projection = generated::ContinuationProjection {
            schema_version: 1,
            run_id: value
                .get("run_id")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            owner_scope: value
                .get("owner_scope")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            policy_id: value
                .get("policy_id")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            policy_revision: number("policy_revision"),
            policy_hash: value
                .get("policy_hash")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            state: value
                .get("state")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            continuation_index: number("continuation_index"),
            max_continuations: number("max_continuations"),
            model_turns: number("used_model_turns"),
            max_model_turns: number("max_model_turns"),
            token_used: number("token_used"),
            cost_used_micros: number("cost_used_micros"),
            stop_reason: value
                .get("stop_reason")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            error_code: value
                .get("error_code")
                .and_then(|v| v.as_str())
                .unwrap_or_default()
                .into(),
            gates: value
                .get("gates")
                .and_then(|v| v.as_array())
                .map(|items| {
                    items
                        .iter()
                        .take(32)
                        .map(|item| generated::ContinuationGateProjection {
                            gate_id: item
                                .get("gate_id")
                                .and_then(|v| v.as_str())
                                .unwrap_or_default()
                                .into(),
                            kind: String::new(),
                            capability_ref: String::new(),
                            status: item
                                .get("status")
                                .and_then(|v| v.as_str())
                                .unwrap_or_default()
                                .into(),
                            evidence_ref: item
                                .get("evidence_ref")
                                .and_then(|v| v.as_str())
                                .unwrap_or_default()
                                .into(),
                            error_code: item
                                .get("error_code")
                                .and_then(|v| v.as_str())
                                .unwrap_or_default()
                                .into(),
                        })
                        .collect()
                })
                .unwrap_or_default(),
        };
        let event = generated::EventEnvelope {
            protocol: Some(protocol()),
            sequence_id: 0,
            task_id: projection.run_id.clone(),
            event_type: "continuation.run".into(),
            payload,
            core_instance_id: self.core_instance_id.clone(),
            session_epoch: self.session_epoch,
            event: Some(generated::event_envelope::Event::Continuation(projection)),
        };
        transport::write_frame(writer, &event.encode_to_vec()).await?;
        Ok(())
    }

